                pubkey: FfiConverterData.read(from: &buf), 
                deviceId: FfiConverterString.read(from: &buf), 
                deviceName: FfiConverterString.read(from: &buf), 
                deviceType: FfiConverterOptionTypeDeviceType.read(from: &buf), 
                fingerprint: FfiConverterString.read(from: &buf), 
                pairedAt: FfiConverterUInt64.read(from: &buf), 
                lastSeen: FfiConverterUInt64.read(from: &buf)
        )
    }

    public static func write(_ value: TrustedPeer, into buf: inout [UInt8]) {
        FfiConverterData.write(value.pubkey, into: &buf)
        FfiConverterString.write(value.deviceId, into: &buf)
        FfiConverterString.write(value.deviceName, into: &buf)
        FfiConverterOptionTypeDeviceType.write(value.deviceType, into: &buf)
        FfiConverterString.write(value.fingerprint, into: &buf)
        FfiConverterUInt64.write(value.pairedAt, into: &buf)
        FfiConverterUInt64.write(value.lastSeen, into: &buf)
    }
}


